struct AdviceEvaluation: Evaluation {
    let helpful = Metric("Helpful")

    var dataset: ArrayLoader<ModelSample<String>> {
        ArrayLoader(samples: [
            ModelSample(prompt: "Explain an index out of range error.", expected: "The array index is outside its bounds."),
        ])
    }

    func subject(from sample: ModelSample<String>) async throws -> ModelSubject<String> {
        let session = LanguageModelSession(instructions: instructions)
        let response = try await session.respond(to: sample.prompt)
        return ModelSubject(value: response.content)
    }

    var evaluators: Evaluators {
        Evaluator { input, subject in
            subject.value.localizedStandardContains("out of range") ? helpful.scoring(1) : helpful.scoring(0)
        }
    }

    func aggregateMetrics(using aggregator: inout MetricsAggregator) {
        aggregator.computeMean(of: helpful)
    }
}

